cd /home/mike/nexus-wt/v120-rc1 && gh run list --workflow CI --limit 60 --json conclusion,status,createdAt,updatedAt,startedAt,event,headBranch > /tmp/claude-1000/ci.json 2>&1; head -c 300 /tmp/claude-1000/ci.json; node -e '
const r=JSON.parse(require("fs").readFileSync("/tmp/claude-1000/ci.json"));
const c={};r.forEach(x=>{const k=x.status+"/"+x.conclusion;c[k]=(c[k]||0)+1});console.log(c);
const d=r.filter(x=>x.conclusion==="success"||x.conclusion==="failure").slice(0,30).map(x=>({run:(new Date(x.updatedAt)-new Date(x.startedAt))/60000,q:(new Date(x.startedAt)-new Date(x.createdAt))/60000,c:x.conclusion,e:x.event}));
const s=a=>a.slice().sort((x,y)=>x-y);const m=a=>s(a)[Math.floor(a.length/2)];
console.log("n",d.length,"median run",m(d.map(x=>x.run)).toFixed(1),"max",Math.max(...d.map(x=>x.run)).toFixed(1),"min",Math.min(...d.map(x=>x.run)).toFixed(1),"median q",m(d.map(x=>x.q)).toFixed(2),"max q",Math.max(...d.map(x=>x.q)).toFixed(1));
const ok=d.filter(x=>x.c==="success");console.log("succ n",ok.length,"median",m(ok.map(x=>x.run)).toFixed(1),"max",Math.max(...ok.map(x=>x.run)).toFixed(1));
console.log(r.slice(0,60).filter(x=>x.conclusion==="failure").map(x=>x.event+" "+x.headBranch));
console.log("span",r[r.length-1].createdAt,r[0].createdAt)'

